// Aggregate data for Claude
const commits = $input.all()[1].json;
const issues = $input.all()[2].json;
const prs = $input.all()[3].json;

const mergedPRs = prs.filter(pr => pr.merged_at !== null);

const weekStart = new Date();
weekStart.setDate(weekStart.getDate() - 7);
const weekEnd = new Date();

const commitList = commits.map(c => ({ sha: c.sha.slice(0,7), message: c.commit.message.split('\n')[0], author: c.commit.author.name, date: c.commit.author.date }));
const issueList = issues.map(i => ({ number: i.number, title: i.title, closed_by: i.closed_by?.login || 'unknown', labels: i.labels.map(l => l.name) }));
const prList = mergedPRs.map(pr => ({ number: pr.number, title: pr.title, merged_by: pr.merged_by?.login || 'unknown', additions: pr.additions || 0, deletions: pr.deletions || 0 }));

const data = {
  repo: $env.GITHUB_REPO,
  week_start: weekStart.toISOString().split('T')[0],
  week_end: weekEnd.toISOString().split('T')[0],
  commits_count: commitList.length,
  commits: commitList.slice(0, 10),
  issues_count: issueList.length,
  issues: issueList.slice(0, 10),
  prs_count: prList.length,
  prs: prList.slice(0, 10)
};

return [{ json: data }];

const claudeResponse = $input.first().json.content[0].text;
const data = $('Aggregate Data').first().json;

// Build prompt based on language
const lang = $env.LANGUAGE || 'EN';

let prompt = '';
if (lang === 'FR') {
  prompt = `Rédige un résumé narratif en français de l'activité du dépôt GitHub « ${data.repo} » pour la semaine du ${data.week_start} au ${data.week_end}.

Activité de la semaine :
- ${data.commits_count} commits, dont : ${data.commits.map(c => `\n  • ${c.sha} — ${c.message} (${c.author})`).join('')}
- ${data.issues_count} issues closes, dont : ${data.issues.map(i => `\n  • #${i.number} — ${i.title} (fermé par @${i.closed_by})`).join('')}
- ${data.prs_count} PRs fusionnées, dont : ${data.prs.map(pr => `\n  • #${pr.number} — ${pr.title} (fusionné par @${pr.merged_by}, +${pr.additions} -${pr.deletions})`).join('')}

Le résumé doit être clair, structuré, et inclure les points clés de la semaine.`;
} else {
  prompt = `Write a clear, structured narrative summary in English of the GitHub repository « ${data.repo} » activity for the week of ${data.week_start} to ${data.week_end}.

Week's activity:
- ${data.commits_count} commits, including: ${data.commits.map(c => `\n  • ${c.sha} — ${c.message} (${c.author})`).join('')}
- ${data.issues_count} closed issues, including: ${data.issues.map(i => `\n  • #${i.number} — ${i.title} (closed by @${i.closed_by})`).join('')}
- ${data.prs_count} merged PRs, including: ${data.prs.map(pr => `\n  • #${pr.number} — ${pr.title} (merged by @${pr.merged_by}, +${pr.additions} -${pr.deletions})`).join('')}

The summary should be clear, structured, and highlight key achievements of the week.`;
}

return [{ json: { repo: data.repo, week_start: data.week_start, week_end: data.week_end, summary: '', lang } }];
